use anyhow::{Context, Result};
use std::path::PathBuf;

/// Resolves the witchcraft assets directory. Priority:
///   1. WARP_ASSETS environment variable
///   2. ~/.gossamer/warp_assets config file
pub fn resolve_warp_assets() -> Option<PathBuf> {
    if let Ok(p) = std::env::var("WARP_ASSETS") {
        let path = PathBuf::from(p);
        if path.exists() {
            return Some(path);
        }
    }
    if let Some(home) = dirs::home_dir() {
        let cfg = home.join(".gossamer/warp_assets");
        if let Ok(s) = std::fs::read_to_string(cfg) {
            let path = PathBuf::from(s.trim());
            if path.exists() {
                return Some(path);
            }
        }
    }
    None
}

pub fn set_warp_assets(path: &str) -> Result<()> {
    let p = PathBuf::from(path);
    if !p.exists() {
        anyhow::bail!("path does not exist: {path}");
    }
    let home = dirs::home_dir().context("cannot determine home directory")?;
    let dir = home.join(".gossamer");
    std::fs::create_dir_all(&dir)?;
    std::fs::write(dir.join("warp_assets"), path.trim())?;
    println!("Assets path saved: {path}");
    Ok(())
}

pub fn show() {
    match resolve_warp_assets() {
        Some(p) => println!("assets: {}", p.display()),
        None => println!(
            "assets: (not set)\n\
             Run `gossamer assets <path>` or set $WARP_ASSETS to the witchcraft assets directory."
        ),
    }
}

pub mod claude_code;

use anyhow::{Context, Result};
use uuid::Uuid;

const SESSION_NAMESPACE: Uuid = Uuid::from_bytes([
    0xb1, 0x2f, 0xa3, 0x44, 0x7c, 0x8e, 0x4d, 0x91,
    0xaa, 0x2c, 0x5e, 0x1f, 0x4b, 0x8d, 0x9c, 0x3e,
]);

const REPO_NAMESPACE: Uuid = Uuid::from_bytes([
    0xc3, 0x5a, 0xb7, 0x11, 0x9d, 0x2c, 0x4e, 0x88,
    0xbc, 0x3d, 0x6f, 0x2a, 0x5c, 0x9e, 0xad, 0x4f,
]);

pub fn embed_and_index(wc_db: &witchcraft::DB) -> Result<()> {
    let Some(assets) = crate::config::resolve_warp_assets() else {
        println!("Run `gossamer assets <path>` pointing at the witchcraft assets directory to enable semantic search.");
        return Ok(());
    };
    let device = witchcraft::make_device();
    let embedder = witchcraft::Embedder::new(&device, &assets)
        .context("failed to load embedder")?;
    witchcraft::embed_chunks(wc_db, &embedder, None)?;
    witchcraft::index_chunks(wc_db, &device)?;
    println!("Search index updated.");
    Ok(())
}

pub fn open_search_db() -> Result<witchcraft::DB> {
    let path = dirs::home_dir()
        .context("cannot determine home directory")?
        .join(".gossamer/search.db");
    Ok(witchcraft::DB::new(path)?)
}

pub fn ingest_sessions(wc_db: &mut witchcraft::DB) -> Result<usize> {
    let conn = crate::db::connect()?;
    let mut stmt = conn.prepare(
        "SELECT session_id, session_name, cwd, agent_name, updated_at FROM sessions",
    )?;

    let rows: Vec<(String, String, String, String, String)> = stmt
        .query_map([], |row| {
            Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?))
        })?
        .flatten()
        .collect();

    let mut count = 0;
    for (session_id, session_name, cwd, agent_name, updated_at) in rows {
        let name = session_name.trim().to_string();
        if name.is_empty() {
            continue;
        }

        let uuid = Uuid::new_v5(&SESSION_NAMESPACE, session_id.as_bytes());
        let metadata = serde_json::json!({
            "source": "session",
            "session_id": session_id,
            "session_name": name,
            "cwd": cwd,
            "agent_name": agent_name,
        })
        .to_string();

        let body = format!("{name}\n{cwd}\n{agent_name}");
        let date = iso8601_timestamp::Timestamp::parse(&updated_at);
        wc_db.add_doc(&uuid, date, &metadata, &body, None)?;
        count += 1;
    }

    Ok(count)
}

/// Scan live JSONL files in ~/.claude/projects/ and backfill session_name for
/// any sessions in the DB whose name is currently blank.
pub fn backfill_session_names() -> Result<usize> {
    let home = std::env::var("HOME").context("HOME not set")?;
    let projects_dir = std::path::PathBuf::from(&home).join(".claude/projects");

    let conn = crate::db::connect()?;

    // Collect session IDs that need a name.
    let mut stmt = conn.prepare(
        "SELECT session_id FROM sessions WHERE session_name = '' OR session_name IS NULL",
    )?;
    let nameless: std::collections::HashSet<String> = stmt
        .query_map([], |row| row.get::<_, String>(0))?
        .flatten()
        .collect();

    if nameless.is_empty() {
        return Ok(0);
    }

    let mut updated = 0usize;

    let Ok(project_dirs) = std::fs::read_dir(&projects_dir) else { return Ok(0) };
    for project in project_dirs.flatten() {
        let Ok(files) = std::fs::read_dir(project.path()) else { continue };
        for file in files.flatten() {
            let path = file.path();
            if path.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue }
            let session_id = match path.file_stem().and_then(|s| s.to_str()) {
                Some(s) => s.to_string(),
                None => continue,
            };
            if !nameless.contains(&session_id) { continue }

            let Ok(f) = std::fs::File::open(&path) else { continue };
            let reader = std::io::BufReader::new(f);
            let mut custom_title: Option<String> = None;
            for line in std::io::BufRead::lines(reader).flatten() {
                if let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) {
                    if v["type"].as_str() == Some("custom-title") {
                        if let Some(t) = v["customTitle"].as_str() {
                            custom_title = Some(t.to_string());
                            break;
                        }
                    }
                }
            }
            let Some(title) = custom_title else { continue };
            conn.execute(
                "UPDATE sessions SET session_name = ?1 WHERE session_id = ?2",
                rusqlite::params![title, session_id],
            )?;
            updated += 1;
        }
    }

    Ok(updated)
}

pub fn ingest_repos(wc_db: &mut witchcraft::DB) -> Result<usize> {
    let conn = crate::db::connect()?;
    let mut stmt = conn.prepare("SELECT directory, remote, name FROM repositories")?;

    let rows: Vec<(String, String, String)> = stmt
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
        .flatten()
        .collect();

    let mut count = 0;
    for (directory, remote, name) in rows {
        let uuid = Uuid::new_v5(&REPO_NAMESPACE, directory.as_bytes());
        let metadata = serde_json::json!({
            "source": "repo",
            "repo_name": name,
            "repo_dir": directory,
            "repo_remote": remote,
        })
        .to_string();

        let body = format!("{name}\n{directory}\n{remote}");
        wc_db.add_doc(&uuid, None, &metadata, &body, None)?;
        count += 1;
    }

    Ok(count)
}

use anyhow::Result;
use std::process::Command;

use crate::db;
use super::index::{
    BRANCH, RepoResolver, fetch_checkpoint_branch, git_show, index_shadow_branches, is_meta_path,
    upsert_session,
};

pub fn run(json: bool) -> Result<()> {
    let conn = db::connect()?;

    let mut stmt = conn.prepare("SELECT id, directory, name FROM repositories")?;
    let repos: Vec<(i64, String, String)> = stmt
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
        .collect::<Result<_, _>>()?;

    if repos.is_empty() {
        if json {
            println!("{}", serde_json::json!({"sessions_indexed": 0}));
        } else {
            println!("No repositories tracked. Run `gossamer init` first.");
        }
        return Ok(());
    }

    let resolver = RepoResolver::new(&conn)?;

    let mut grand_total = 0usize;

    for (repo_id, dir, name) in &repos {
        match refresh_repo(&conn, *repo_id, dir, &resolver) {
            Ok(0) => { if !json { println!("'{}': up to date.", name); } }
            Ok(n) => {
                if !json { println!("'{}': {} new session(s) indexed.", name, n); }
                grand_total += n;
            }
            Err(e) => eprintln!("'{}': error — {}", name, e),
        }
    }

    let names_filled = crate::ingest::backfill_session_names().unwrap_or(0);

    if json {
        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
            "sessions_indexed": grand_total,
            "names_backfilled": names_filled,
        }))?);
    } else {
        println!();
        if grand_total > 0 {
            println!("{} new session(s) indexed.", grand_total);
        } else {
            println!("All repositories up to date.");
        }
        if names_filled > 0 {
            println!("{} session name(s) backfilled.", names_filled);
        }
    }

    Ok(())
}

fn refresh_repo(conn: &rusqlite::Connection, repo_id: i64, repo_dir: &str, resolver: &RepoResolver) -> Result<usize> {
    fetch_checkpoint_branch(repo_dir);

    // Shadow branches advance on every prompt, so we always sweep them — even
    // when the checkpoint head is unchanged, an active session can have new
    // turns visible only on its shadow ref.
    let shadow_count = index_shadow_branches(conn, repo_id, repo_dir, resolver).unwrap_or(0);

    // Check checkpoint branch exists.
    let check = Command::new("git")
        .args(["rev-parse", "--verify", BRANCH])
        .current_dir(repo_dir)
        .output()?;

    if !check.status.success() {
        return Ok(shadow_count);
    }

    let current_head = String::from_utf8(check.stdout)?.trim().to_string();

    // Load stored watermark.
    let stored_head: Option<String> = conn.query_row(
        "SELECT last_indexed_commit FROM repositories WHERE directory = ?1",
        [repo_dir],
        |row| row.get(0),
    ).ok().flatten();

    if stored_head.as_deref() == Some(current_head.as_str()) {
        return Ok(shadow_count); // checkpoint unchanged; shadow may still have new turns
    }

    // Collect metadata paths: added or modified since watermark (or all if first run).
    let meta_paths: Vec<String> = if let Some(ref last) = stored_head {
        // git diff gives a deduplicated file list between two tree states, so each
        // session appears at most once even if it was checkpointed many times.
        let out = Command::new("git")
            .args(["diff", "--name-only", "--diff-filter=AM", last, BRANCH])
            .current_dir(repo_dir)
            .output()?;
        String::from_utf8(out.stdout)?
            .lines()
            .filter(|l| is_meta_path(l))
            .map(str::to_string)
            .collect()
    } else {
        let out = Command::new("git")
            .args(["ls-tree", "-r", "--name-only", BRANCH])
            .current_dir(repo_dir)
            .output()?;
        String::from_utf8(out.stdout)?
            .lines()
            .filter(|l| is_meta_path(l))
            .map(str::to_string)
            .collect()
    };

    let user = std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .unwrap_or_else(|_| "unknown".to_string());

    let mut count = 0;
    for meta_path in &meta_paths {
        let jsonl_path = format!(
            "{}full.jsonl",
            &meta_path[..meta_path.len() - "metadata.json".len()]
        );
        let meta_bytes = match git_show(repo_dir, meta_path) {
            Ok(b) => b,
            Err(e) => { eprintln!("  skipping {}: {}", meta_path, e); continue; }
        };
        let jsonl_bytes = match git_show(repo_dir, &jsonl_path) {
            Ok(b) => b,
            Err(_) => continue,
        };
        match crate::parsers::dispatch_session(&meta_bytes, &jsonl_bytes) {
            Ok(p) => {
                let resolved_id = resolver.resolve(&p.cwd, Some(repo_id));
                upsert_session(conn, &p.session_id, &p.agent_name, &user,
                               &p.created_at, &p.updated_at, &p.cwd, &p.session_name,
                               &p.branch, resolved_id, p.name_is_explicit, p.tokens_used)?;
                count += 1;
            }
            Err(e) => eprintln!("  skipping {}: {}", meta_path, e),
        }
    }

    // Advance watermark.
    conn.execute(
        "UPDATE repositories SET last_indexed_commit = ?1 WHERE directory = ?2",
        rusqlite::params![current_head, repo_dir],
    )?;

    Ok(count + shadow_count)
}

